"""Allowlisted actionable diagnostics; never raw exceptions/world packets."""
from app.graph.repository import PreconditionFailed
CODES={'DEMO_PREREQUISITE_EVENT_REQUIRED','DEMO_CLOCK_BEFORE_BASELINE','DEMO_STAGE_OR_SOURCE_MISMATCH','DEMO_STAGE_ORDER','DEMO_CASE_ALREADY_RELEASED_OR_UNBOUND','DEMO_ACTIVE_INSPECTION_REQUIRED','DEMO_INSPECTION_BINDING_LIFECYCLE','DEMO_OBSERVATION_BEFORE_INSPECTION','DEMO_APPROVED_PLAN_REQUIRED','DEMO_PLAN_SCOPE','DEMO_EXACT_APPROVAL_REQUIRED','DEMO_COMPLETED_WORK_REQUIRED','DEMO_COMPLETED_WORK_SCOPE','DEMO_QUALIFYING_INDEPENDENT_OUTCOME_REQUIRED','PRIVATE_DEMO_HOST_CONFIGURATION_REQUIRED','PRIVATE_DEMO_DIRECTORY_REQUIRED'}
class DemoBlocked(PreconditionFailed):
 def __init__(self,code):
  if code not in CODES:raise ValueError('UNKNOWN_SAFE_BLOCKER')
  self.blocker_code=code;super().__init__('SCENARIO_PREREQUISITE')
